import boto3

AWS_REGION = 'us-west-2'

def get_textract_client():
    return boto3.client('textract', region_name=AWS_REGION)

def start_document_analysis(client, document_location, feature_types):
    response = client.start_document_analysis(
        DocumentLocation=document_location,
        FeatureTypes=feature_types
    )
    return response

def get_document_analysis_result(client, job_id):
    response = client.get_document_analysis(JobId=job_id)
    return response

import boto3

def extract_key_values(document):
    textract_client = boto3.client('textract')
    response = textract_client.analyze_document(
        Document={'Bytes': document},
        FeatureTypes=['FORMS'])
    key_values = {}
    for block in response['Blocks']:
        if block['BlockType'] == 'KEY_VALUE_SET':
            key = None
            value = None
            for child_id in block['Relationships'][0]['Ids']:
                child_block = next(b for b in response['Blocks'] if b['Id'] == child_id)
                if child_block['BlockType'] == 'WORD':
                    if key is None:
                        key = child_block['Text']
                    else:
                        value = child_block['Text']
            if key and value:
                key_values[key] = value
    return key_values

import boto3

def extract_tables(document_path):
    client = boto3.client('textract')
    with open(document_path, 'rb') as document:
        imageBytes = document.read()
    response = client.analyze_document(
        Document={'Bytes': imageBytes},
        FeatureTypes=['TABLES'])
    blocks = response['Blocks']
    table_info = {}
    for block in blocks:
        if block['BlockType'] == 'TABLE':
            table_info[block['Id']] = {
                'Row': block['Row'],
                'Column': block['Column'],
                'Text': block['Text']
            }
    return table_info

import boto3

def extract_layout(document_path):
    textract_client = boto3.client('textract')
    with open(document_path, 'rb') as document:
        image_bytes = document.read()
    response = textract_client.detect_document_text(
        Document={'Bytes': image_bytes}
    )
    layout_elements = []
    for item in response['Blocks']:
        if item['BlockType'] in ['LINE', 'WORD', 'TABLE', 'CELL']:
            layout_elements.append(item)
    return layout_elements

import boto3

def extract_text(document_image):
    textract_client = boto3.client('textract')
    response = textract_client.detect_document_text(
        Document={'Bytes': document_image}
    )
    text = ''
    for item in response['Blocks']:
        if item['BlockType'] == 'LINE':
            text += item['Text'] + ' '
    return text
